S(82, 'The total cost of buying a car', 'Find the out-the-door price of a vehicle and check a car before buying',
  main=[
    q('Maya buys a car priced at $24,000 in New Jersey, where sales tax is 6.625%. In this example, tax applies to the price only. How much is the sales tax?', '$1,590',
      [('$159', 'Uses 0.6625% instead of 6.625%'), ('$15,900', 'Uses 66.25% because the decimal moved the wrong way'), ('$25,590', 'Gives the price plus tax instead of the tax')],
      intro='Buying a car costs more than its price. Sales tax is a percent of the price: tax = price × rate as a decimal. New Jersey\'s rate is 6.625% (0.06625).',
      fb='$24,000 × 0.06625 = $1,590.', calc=1590, sub='Sales tax on a car', eff='NJ rate 6.625% since 2018-01-01'),
    q('A car is priced at $24,000. Tax is $1,590, the dealer documentation fee is $399, and title and registration cost $260. What is the out-the-door price?', '$26,249',
      [('$24,659', 'Adds the fees but leaves out the sales tax'), ('$25,590', 'Adds the tax but leaves out both fees'), ('$24,000', 'Treats the price tag as the full cost')],
      intro='The out-the-door price is the total you pay to drive away: vehicle price + sales tax + dealer fees + title and registration + any add-ons.',
      fb='$24,000 + $1,590 + $399 + $260 = $26,249.', calc=26249, sub='Out-the-door price'),
    q('A salesperson asks, "What monthly payment do you want?" Why is it smarter to negotiate the out-the-door price?', 'A low payment can hide a higher price',
      [('Monthly payments include no interest, so they show the true cost', 'Believes a payment contains no interest'), ('Dealers are not allowed to change a price once a payment is named', 'Invents a rule that does not exist'), ('Talking about price is rude, so the payment is a friendlier way to agree', 'Lets comfort replace comparison')],
      intro='A payment depends on price, rate, and loan length. A dealer can meet any payment target by stretching the loan or raising the price, so agree on the total price first, then discuss financing.',
      fb='Negotiate the total price; a longer loan can make a higher price look affordable.', sub='Price vs payment', how=True),
    q('In a state with no extra used-car warranty law, a used car\'s Buyers Guide is checked "AS IS - NO DEALER WARRANTY." What does that mean?', 'The buyer pays for repairs after the sale',
      [('The dealer must fix any problem for one full year after the sale', 'Reverses the meaning of "as is"'), ('The car has passed a state inspection that guarantees its condition', 'Confuses a sticker with an inspection'), ('The price is final and the dealer will not negotiate it at all', 'Confuses warranty with price')],
      intro='Federal rules require dealers to post a Buyers Guide on used cars. It says whether the car comes with a warranty or is sold "as is." Some states, including New Jersey, require a limited warranty on many used cars, so check your state\'s rules.',
      fb='"As is" means no dealer warranty: repairs after the sale are the buyer\'s cost.', sub='Buyers Guide', eff='FTC Used Car Rule as of 2026'),
    q('Before buying a used car from a private seller, which step best protects Maya?', 'Pay for an independent mechanic\'s inspection',
      [('Trust the seller\'s description because they have owned it for years', 'Relies on the seller, who wants a sale'), ('Skip the test drive so the car does not get more miles on it', 'Gives up the chance to notice problems'), ('Judge the condition from the photos in the online listing', 'Photos hide mechanical problems')],
      intro='A pre-purchase inspection by a mechanic you choose costs a little and can reveal expensive problems. Also take a test drive and check the vehicle history report.',
      fb='An independent inspection finds problems the seller may not mention.', sub='Inspection', how=True),
  ],
  back=[
    concept('Taxes and fees on a purchase', 'The out-the-door price adds a percent tax and flat fees to the price.', [
      q('What is 6% sales tax on a $10,000 car?', '$600',
        [('$60', 'Uses 0.6%'), ('$6,000', 'Uses 60%'), ('$10,600', 'Gives the total')],
        intro='Tax = price × rate. Write the percent as a decimal: 6% = 0.06.',
        fb='$10,000 × 0.06 = $600.', calc=600, sub='Percent tax'),
      q('A $10,000 car has 6% sales tax. What is the price with tax?', '$10,600',
        [('$10,060', 'Uses 0.6% tax'), ('$16,000', 'Uses 60% tax'), ('$600', 'Gives the tax only')],
        intro='Price with tax = price + tax, or price × (1 + rate).',
        fb='$10,000 × 1.06 = $10,600.', calc=10600, sub='Price with tax'),
      q('Which is a one-time cost of buying a car?', 'The title fee',
        [('The monthly insurance premium, paid as long as you drive', 'Ongoing cost'), ('Gasoline, bought every week or two', 'Ongoing cost'), ('Oil changes every few thousand miles', 'Ongoing cost')],
        intro='Buying costs are paid once (tax, title, registration at purchase, dealer fees). Owning costs repeat (insurance, fuel, maintenance).',
        fb='The title fee is paid once when ownership transfers.', sub='One-time vs ongoing'),
      q('What is a dealer documentation ("doc") fee?', 'A dealer charge for paperwork',
        [('A government tax that every buyer must pay to the state', 'Confuses a dealer fee with a tax'), ('A refundable deposit returned after one year', 'Invents a refund'), ('A discount for buyers who bring their own documents', 'Reverses a fee')],
        intro='Doc fees are set by the dealer, not the government. Ask about them early and include them in the out-the-door price.',
        fb='A doc fee is the dealer\'s own charge for processing paperwork.', sub='Doc fee'),
      q('A $5,000 car has $350 tax and $300 in fees. What is the total cost?', '$5,650',
        [('$5,350', 'Leaves out the fees'), ('$5,300', 'Leaves out the tax'), ('$650', 'Gives the extras only')],
        fb='$5,000 + $350 + $300 = $5,650.', calc=5650, sub='Total cost'),
    ]),
    math('Find sales tax and the final cost with tax', 'Sales tax on a car is a percent of the price.', 'grade_7', 63),
    math('Find a percent fee and the total with the fee', 'Fees and taxes are added to the price to get the out-the-door total.', 'grade_7', 65),
  ],
  go=[
    deeper('New, used, and certified pre-owned', [
      q('A new $30,000 car loses 20% of its value in the first year. What is it worth after one year?', '$24,000',
        [('$6,000', 'Gives the loss instead of the value'), ('$29,400', 'Uses 2% instead of 20%'), ('$36,000', 'Adds 20% instead of subtracting')],
        intro='New cars lose value (depreciate) fastest in the first years. That is why a lightly used car can cost much less than a new one.',
        fb='$30,000 × 0.80 = $24,000.', calc=24000, sub='First-year depreciation'),
      q('What is a certified pre-owned (CPO) car?', 'A used car inspected and backed by a warranty',
        [('A brand-new car that has never been registered to anyone', 'Describes a new car'), ('A used car whose price is set by the government', 'Invents price control'), ('Any used car sold by a private seller with a receipt', 'Confuses a receipt with certification')],
        intro='CPO programs, usually run by manufacturers, inspect late-model used cars and add an extended warranty, at a higher price than a regular used car.',
        fb='CPO cars are inspected used cars with an added warranty.', sub='Certified pre-owned'),
      q('A vehicle history report shows a "salvage" title. What does that mean?', 'An insurer once declared it a total loss',
        [('The car has had only one careful owner since it was new', 'Misreads a warning as a selling point'), ('The car was built with recycled parts to protect the environment', 'Takes the word literally'), ('The car qualifies for a lower sales tax rate', 'Invents a tax rule')],
        intro='History reports (from services such as Carfax or AutoCheck) show past accidents, title brands such as salvage or flood, and odometer readings.',
        fb='A salvage title means the car was once a total loss; it may have hidden damage and lower resale value.', sub='History reports', how=True),
      q('Where can a buyer check a car\'s VIN for open safety recalls for free?', 'NHTSA\'s recall lookup',
        [('Only the seller\'s word, since recall records are private', 'Believes recall records are secret'), ('The price on the car\'s window sticker', 'A price is not a recall record'), ('A paid membership site that sells recall lists', 'The government lookup is free')],
        intro='The National Highway Traffic Safety Administration (NHTSA) lets anyone search a 17-character vehicle identification number (VIN) for unrepaired recalls. Recall repairs are free at a dealer.',
        fb='NHTSA\'s free VIN lookup shows open recalls.', sub='Recalls', how=True),
      q('Car A: used, $15,000, expected 3-year repairs $2,400. Car B: certified pre-owned, $17,500, warranty limits repairs to about $400. Which has the lower expected 3-year cost?', 'Car A, by $500',
        [('Car B, by $500', 'Reverses the comparison'), ('Car A, by $2,500', 'Compares only the prices'), ('Car B, by $2,000', 'Compares only the repairs')],
        fb='A: $15,000 + $2,400 = $17,400. B: $17,500 + $400 = $17,900. A costs $500 less.', calc=500, pick=-1, shared=True, sub='Comparing total cost'),
    ]),
    deeper('Negotiating, add-ons, and trade-ins', [
      q('Before visiting a dealer, Maya looks up the car\'s typical selling price on several pricing guides. Why?', 'To know a fair offer before negotiating',
        [('Because dealers must sell at the price shown on any website', 'Invents a rule'), ('So she can skip reading the purchase contract', 'Research does not replace reading'), ('Because online prices already include her tax and fees', 'Guides show vehicle prices, not her total')],
        intro='Pricing guides (such as Kelley Blue Book or Edmunds) and listings for similar cars show what buyers typically pay. Getting written quotes from several dealers also helps.',
        fb='Research gives a fair target price to negotiate toward.', sub='Researching price', how=True),
      q('The finance office adds an extended warranty ($1,800), VIN etching ($300), and paint protection ($600). How much do these add-ons add to the cost?', '$2,700',
        [('$2,400', 'Leaves out the paint protection'), ('$2,100', 'Leaves out the VIN etching'), ('$1,800', 'Counts only the warranty')],
        intro='Add-ons are extra products sold with a car. They raise the price, and if financed, you pay interest on them too.',
        fb='$1,800 + $300 + $600 = $2,700.', calc=2700, sub='Add-ons'),
      q('Can Maya refuse the add-ons?', 'Yes; they are optional',
        [('No; federal law requires every buyer to purchase them', 'Invents a requirement'), ('Only if she pays the full price in cash with no loan', 'Invents a condition'), ('No; once listed on the worksheet, they cannot be removed', 'Believes a draft is final')],
        intro='Extended warranties, etching, and protection packages are optional. A dealer may not say they are required to get a loan if they are not.',
        fb='Add-ons are optional; ask for them to be removed before signing.', sub='Declining add-ons', how=True),
      q('Sam\'s current car is worth $6,000 as a trade-in, but Sam still owes $8,000 on its loan. What is Sam\'s negative equity?', '$2,000',
        [('$6,000', 'Gives the trade-in value'), ('$8,000', 'Gives the loan balance'), ('$14,000', 'Adds the two amounts')],
        intro='Equity = value − amount owed. When you owe more than the car is worth, the difference is negative equity ("being underwater").',
        fb='$8,000 − $6,000 = $2,000 owed beyond the car\'s value.', calc=2000, sub='Negative equity'),
      q('Sam rolls the $2,000 negative equity into a new $20,000 car loan. How much does Sam now borrow?', '$22,000',
        [('$18,000', 'Subtracts the negative equity'), ('$20,000', 'Ignores the rolled-over balance'), ('$26,000', 'Adds the trade-in value')],
        intro='Rolling negative equity into a new loan adds the old debt to the new one, so you start the new loan even further underwater.',
        fb='$20,000 + $2,000 = $22,000.', calc=22000, sub='Rolling over debt'),
    ]),
  ],
  nat=('Spending', 'Calculate the total cost of buying a vehicle and evaluate a used car before purchase'), nj=['CDM', 'PB'],
  status='time_sensitive', sources=[NJ_TAX, FTC_USED, NHTSA], extra=['Finding the out-the-door price', 'Checking a VIN for recalls', 'Declining add-ons'])

