        [('Offer 2, by $571.20', 'Reverses the comparison'), ('Offer 2, by $3,000', 'Counts the rebate but not the interest'), ('Offer 1, by $3,000', 'Ignores the interest paid on Offer 2')],
        intro='Dealers sometimes offer a choice: a low rate or a cash rebate. Compare the total paid under each.',
