# ---------------------------------------------------------------- S85
S(85, 'Leasing vs buying a car', 'Explain lease terms and compare the cost of leasing with buying',
  main=[
    q('What does it mean to lease a car?', 'Paying to use it for a set term, then returning it',
      [('Buying the car outright with one cash payment', 'Describes a cash purchase'), ('Borrowing to buy the car and keeping it after payoff', 'Describes a loan'), ('Renting a car for one weekend trip', 'Describes a short rental')],
      intro='A lease is a long-term rental, often 2 to 4 years. You pay for the car\'s expected loss in value plus a finance charge, then return it or buy it at a set price.',
      fb='A lease pays for use over a term; ownership stays with the leasing company.', sub='What a lease is'),
    q('A lease allows 10,000 miles a year for 3 years and charges $0.25 for each extra mile. Maya drives 36,000 miles. What is the charge?', '$1,500',
      [('$9,000', 'Charges for every mile driven'), ('$6,000', 'Gives the extra miles, not dollars'), ('$2,500', 'Charges for one year\'s allowance')],
      intro='Leases have mileage limits. Extra miles are charged at a set rate when the car is returned.',
      fb='Allowed 30,000; extra 6,000 × $0.25 = $1,500.', calc=1500, sub='Mileage overage'),
    q('A car has a capitalized cost of $30,000 and a residual value of $18,000 after 36 months. What is the monthly depreciation part of the payment?', '$333.33',
      [('$833.33', 'Divides the full cost by 36'), ('$500.00', 'Divides the residual by 36'), ('$12,000.00', 'Gives the total depreciation')],
      intro='Capitalized cost is the lease\'s agreed price. Residual value is the predicted value at the end. The payment covers the depreciation (cap cost − residual) spread over the months, plus a finance charge and tax.',
      fb='($30,000 − $18,000) ÷ 36 = $333.33.', calc=333.33, sub='Lease payment'),
    q('A lease needs $2,000 at signing and 36 payments of $399. What is the total cost of the lease?', '$16,364',
      [('$14,364', 'Leaves out the amount due at signing'), ('$18,364', 'Counts the signing amount twice'), ('$2,399', 'Adds one payment')],
      fb='$2,000 + 36 × $399 = $2,000 + $14,364 = $16,364.', calc=16364, sub='Total lease cost'),
    q('Who is usually a better fit for leasing?', 'A low-mileage driver who wants a new car often',
      [('A driver who goes 25,000 miles a year and keeps cars a decade', 'Mileage charges and no ownership'), ('A buyer who wants to customize the car and own it outright', 'Leases limit changes'), ('A person who wants never to have a monthly car payment', 'Leases always have payments')],
      intro='Leasing tends to fit drivers who stay under mileage limits, keep the car in good shape, and like changing cars every few years. Buying fits drivers who keep cars a long time.',
      fb='Leasing fits low mileage and frequent upgrades.', sub='Who should lease'),
  ],
  back=[
    concept('Using vs owning', 'A lease is paying to use; a loan is paying to own. The difference explains every lease term.', [
      q('At the end of a lease, what can the driver usually do?', 'Return the car or buy it at the set price',
        [('Keep the car free of charge forever', 'Ignores the end-of-lease terms'), ('Sell the car and keep the money', 'The driver does not own it'), ('Stop paying and drive it until it finally breaks', 'Breaks the contract')],
        intro='The lease contract states a purchase option price, often equal to the residual value.',
        fb='Return the car or buy it at the contract price.', sub='End of lease'),
      q('In a lease, what is the residual value?', 'The predicted value at the end',
        [('The amount paid up front at signing', 'Confuses with the down payment'), ('The monthly finance charge', 'Confuses with the rent charge'), ('The car\'s price when new', 'Confuses with the cap cost')],
        fb='Residual value is the expected value when the lease ends.', sub='Residual value'),
      q('What are "excess wear and tear" charges?', 'Fees for damage beyond normal use',
        [('Monthly fees for routine oil changes', 'Confuses with maintenance'), ('Taxes on the car\'s registration', 'Confuses with a tax'), ('Charges for driving under the mileage limit', 'Reverses the mileage rule')],
        intro='Lessees return the car in the condition the lease requires. Dents, stains, and worn tires beyond the standard can be charged.',
        fb='Damage beyond normal wear is charged at return.', sub='Wear and tear'),
      q('A lease costs $350 a month for 36 months. How much are the payments in total?', '$12,600',
        [('$10,500', 'Uses 30 months'), ('$4,200', 'Uses 12 months'), ('$386', 'Adds')],
        fb='36 × $350 = $12,600.', calc=12600, sub='Total payments'),
      q('After paying off a car loan, the owner has the car. After a lease ends, what does the driver own?', 'Nothing, unless they buy the car',
        [('Half of the car\'s value', 'Invents shared ownership'), ('The car, with no further cost', 'Confuses with a paid-off loan'), ('A credit toward any future purchase', 'Invents a credit')],
        intro='Equity is the value you own. Loan payments build equity; lease payments do not.',
        fb='A lease builds no ownership; a paid-off loan does.', sub='Equity'),
    ]),
    math('Solve multistep problems with rational numbers', 'Lease costs combine payments, fees, and charges.', 'grade_7', 29),
    math('Divide multi-digit decimals', 'Lease payments spread a dollar amount over months.', 'grade_6', 20),
  ],
  go=[
    deeper('Inside the lease payment', [
      q('A lease has a money factor of 0.0025. Multiply by 2,400 to compare with an APR. What APR does it equal?', '6%',
        [('0.25%', 'Reads the money factor as a percent'), ('2.5%', 'Multiplies by 1,000'), ('24%', 'Multiplies by 9,600')],
        intro='Leases state the finance charge as a money factor, a small decimal. Money factor × 2,400 is roughly the equivalent APR.',
        fb='0.0025 × 2,400 = 6, about 6% APR.', calc=6, sub='Money factor'),
      q('The monthly finance charge is (cap cost + residual) × money factor. For $30,000 and $18,000 with a money factor of 0.0025, what is it?', '$120',
        [('$75', 'Uses only the cap cost'), ('$45', 'Uses only the residual'), ('$30', 'Subtracts instead of adding')],
        fb='($30,000 + $18,000) × 0.0025 = $120.', calc=120, sub='Rent charge'),
      q('Depreciation is $333.33 a month and the finance charge is $120. What is the monthly payment before tax?', '$453.33',
        [('$213.33', 'Subtracts the finance charge'), ('$333.33', 'Leaves out the finance charge'), ('$573.33', 'Counts the finance charge twice')],
        fb='$333.33 + $120 = $453.33.', calc=453.33, sub='Building the payment'),
      q('Why do some experts advise against a large down payment on a lease?', 'It may be lost if the car is totaled',
        [('Down payments on leases earn very high interest', 'Confuses a down payment with savings'), ('Leasing companies are not allowed to accept them', 'Invents a rule'), ('It always raises the monthly payment', 'Reverses the effect')],
        intro='If a leased car is totaled early, insurance and GAP coverage pay the leasing company; money paid up front is usually not returned.',
        fb='Cash paid up front on a lease can be lost if the car is totaled.', sub='Lease down payments'),
      q('Maya wants to end her lease after 18 of 36 months. What should she expect?', 'Early termination charges',
        [('A refund of every payment made so far', 'Invents a refund'), ('No cost, since leases can end at any time', 'Ignores the contract'), ('Ownership of half the car', 'Invents shared ownership')],
        intro='Ending a lease early often triggers large fees, sometimes most of the remaining payments.',
        fb='Early termination usually costs a lot; read that section before signing.', sub='Ending early', how=True),
    ]),
    deeper('Lease or buy: the three-year comparison', [
      q('After 3 years of buying, Maya\'s car is worth $18,000 and she still owes $6,000. What is her equity?', '$12,000',
        [('$24,000', 'Adds the amounts'), ('$18,000', 'Gives the car\'s value'), ('$6,000', 'Gives the amount owed')],
        intro='Equity = value − amount owed.',
        fb='$18,000 − $6,000 = $12,000.', calc=12000, sub='Equity after 3 years'),
      q('Over 3 years, buying cost Maya $3,000 down plus 36 payments of $500. Her equity is $12,000. What is the net cost of buying for those 3 years?', '$9,000',
        [('$21,000', 'Ignores the equity'), ('$33,000', 'Adds the equity'), ('$18,000', 'Leaves out the down payment')],
        intro='Net cost = total paid − equity kept, because the equity is value she still owns.',
        fb='$3,000 + 36 × $500 = $21,000; $21,000 − $12,000 = $9,000.', calc=9000, sub='Net cost of buying'),
      q('Leasing a car for 3 years costs $16,364 in total. Buying has a net cost of $9,000. Which costs less, and by how much?', 'Buying, by $7,364',
        [('Leasing, by $7,364', 'Reverses the comparison'), ('Buying, by $25,364', 'Adds the costs'), ('Leasing, by $9,000', 'Uses only buying\'s cost')],
        fb='$16,364 − $9,000 = $7,364 less by buying.', calc=7364, pick=-1, shared=True, sub='Comparing'),
      q('Why are lease payments often lower than loan payments on the same car?', 'You pay only for the expected depreciation',
        [('Leasing companies do not charge any interest', 'Leases have a finance charge'), ('Leased cars are exempt from every tax', 'Invents a tax rule'), ('Leases last longer than loans', 'Usually the reverse')],
        fb='A lease covers the loss in value, not the whole price.', sub='Why payments differ'),
      q('Maya drives 20,000 miles a year and keeps cars for 8 years. Which choice likely costs her less?', 'Buying',
        [('Leasing, since mileage charges are always waived', 'Ignores mileage charges'), ('Leasing a new car every year for eight years', 'Repeats the costliest early years'), ('Renting daily for eight years', 'Daily rentals cost far more')],
        fb='High mileage and long ownership favor buying.', sub='Matching the choice to the driver'),
    ]),
  ],
  nat=('Spending', 'Compare the costs and benefits of leasing and buying a vehicle'), nj=['CDM', 'PB'],
  sources=[FTC_LEASE], extra=['Reading a lease', 'Comparing lease and buy over 3 years'])
